import { hashString, mulberry32 } from './data.js'

const cache = new Map()

function scaleMidi(root, scale, degree, octave = 0) {
  const length = scale.length
  const octaveShift = Math.floor(degree / length)
  const index = ((degree % length) + length) % length
  return root + scale[index] + (octaveShift + octave) * 12
}

function chordDegrees(degree) {
  return [degree, degree + 2, degree + 4]
}

const DRUM_STYLES = {
  'aurora-drive': {
    kick: [0, 2],
    snare: [1, 3],
    hatStep: 0.5,
    ghostKick: [],
    sparkle: 0.1,
  },
  'glass-horizon': {
    kick: [0, 1.5, 2.5],
    snare: [1, 3],
    hatStep: 0.25,
    ghostKick: [3.75],
    sparkle: 0.18,
  },
  'night-circuit': {
    kick: [0, 0.75, 2, 2.75],
    snare: [1, 3],
    hatStep: 0.25,
    ghostKick: [1.75, 3.5],
    sparkle: 0.22,
  },
  'thunder-crown': {
    kick: [0, 1, 2, 3],
    snare: [1, 3],
    hatStep: 0.25,
    ghostKick: [0.5, 2.5],
    sparkle: 0.3,
  },
}

/**
 * A deterministic miniature arrangement. The generated chart is based on the
 * same melody/accent data that the synthesizer receives, so audio and tiles
 * always share a pulse without shipping any binary music files.
 */
export function buildComposition(track) {
  if (cache.has(track.id)) return cache.get(track.id)

  const beat = 60 / track.bpm
  const barLength = beat * 4
  const eighth = beat / 2
  const bars = track.bars
  const duration = track.duration
  const random = mulberry32((track.seed || hashString(track.id)) >>> 0)
  const style = DRUM_STYLES[track.id] || DRUM_STYLES['aurora-drive']
  const events = []
  const pads = []
  const bass = []
  const drums = []
  const accents = []
  const introBars = 2
  const outroBars = 2

  for (let bar = 0; bar < bars; bar += 1) {
    const barTime = bar * barLength
    const section = bar < introBars ? 0 : bar >= bars - outroBars ? 2 : 1
    const phrase = Math.floor(bar / 4)
    const progressionIndex = bar % track.progression.length
    const degree = track.progression[progressionIndex]
    const chord = chordDegrees(degree)

    pads.push({
      time: barTime,
      duration: barLength * 0.98,
      notes: chord.map((item) => scaleMidi(track.root, track.scale, item, 0)),
      velocity: section === 1 ? 0.9 : 0.6,
    })

    const bassRoot = scaleMidi(track.root, track.scale, degree, -1)
    for (const offset of track.bassPattern) {
      const time = barTime + offset * beat
      if (time >= duration - 0.1) continue
      const octaveLift = offset === 0 ? 0 : 0
      bass.push({
        time,
        duration: offset === 0 ? beat * 0.9 : beat * 0.4,
        midi: bassRoot + octaveLift,
        velocity: offset === 0 ? 0.95 : 0.7,
      })
    }

    for (const offset of style.kick) {
      drums.push({
        type: 'kick',
        time: barTime + offset * beat,
        velocity: offset === 0 ? 1 : 0.8,
      })
    }
    for (const offset of style.ghostKick) {
      if (random() < 0.34 + style.sparkle) {
        drums.push({ type: 'kick', time: barTime + offset * beat, velocity: 0.42 })
      }
    }
    for (const offset of style.snare) {
      drums.push({ type: 'snare', time: barTime + offset * beat, velocity: 0.78 })
    }

    if (section > 0) {
      for (let step = 0; step < 4; step += style.hatStep) {
        const accentHat = step % 1 === 0
        drums.push({
          type: 'hat',
          time: barTime + step * beat,
          velocity: accentHat ? 0.55 : 0.3,
        })
      }
    }

    const activeLead = track.leadPattern.map((value) => Boolean(value))
    if (section === 0) {
      for (let step = 0; step < 8; step += 1) {
        if (step % 4 === 0) activeLead[step] = true
        else activeLead[step] = false
      }
    } else if (section === 2) {
      for (let step = 0; step < 8; step += 1) {
        if (step === 0 || step === 4) activeLead[step] = true
        else activeLead[step] = false
      }
    }

    for (let step = 0; step < 8; step += 1) {
      if (!activeLead[step]) continue
      if (section === 1 && random() < 0.12) continue

      const noteTime = barTime + step * eighth
      if (noteTime >= duration - 0.18) continue

      const chordTone = chord[Math.floor(random() * chord.length)]
      const colorTone = random() < 0.24 ? 1 : 0
      const degreeIndex = chordTone + colorTone
      const octave = random() < 0.16 ? 2 : 1
      const midi = scaleMidi(track.root, track.scale, degreeIndex, octave)
      const longNote = step === 0 && bar % 8 === 4 && section === 1
      const noteEighthLength = longNote ? 4 : random() < 0.16 ? 2 : 1
      const noteDuration = noteEighthLength * eighth
      const laneHint = (degreeIndex + step + phrase) % 4
      const strength = 0.62 + random() * 0.3 + (step % 2 === 0 ? 0.08 : 0)

      events.push({
        time: noteTime,
        duration: noteDuration,
        midi,
        velocity: 0.65 + random() * 0.2,
        strength: Math.min(1, strength),
        laneHint,
        sustain: noteDuration,
        kind: 'lead',
      })

      if (section === 1 && step % 4 === 0 && random() < 0.32) {
        const harmonyMidi = scaleMidi(track.root, track.scale, degreeIndex + 2, octave)
        events.push({
          time: noteTime + 0.004,
          duration: noteDuration * 0.8,
          midi: harmonyMidi,
          velocity: 0.46,
          strength: 0.66,
          laneHint: (laneHint + 2) % 4,
          sustain: noteDuration * 0.8,
          kind: 'harmony',
        })
      }

      if (track.bpm >= 140 && section === 1 && random() < 0.09) {
        const fillTime = noteTime + eighth * 0.5
        const fillMidi = scaleMidi(track.root, track.scale, degreeIndex + 1, octave)
        events.push({
          time: fillTime,
          duration: eighth * 0.7,
          midi: fillMidi,
          velocity: 0.42,
          strength: 0.54,
          laneHint: (laneHint + 1) % 4,
          sustain: eighth * 0.7,
          kind: 'fill',
        })
      }
    }

    if (section === 1 && bar % 4 === 0) {
      accents.push({ time: barTime, strength: 1 })
    }
  }

  const lastLead = events.reduce((max, event) => Math.max(max, event.time + event.duration), 0)
  const composition = {
    trackId: track.id,
    beat,
    barLength,
    duration,
    events: events
      .filter((event) => event.time < duration - 0.2)
      .sort((a, b) => a.time - b.time),
    pads,
    bass,
    drums: drums.filter((drum) => drum.time < duration - 0.05),
    accents,
    musicalEnd: Math.max(lastLead, duration - 0.5),
  }
  cache.set(track.id, composition)
  return composition
}

function makeNoiseBuffer(context, seconds = 2) {
  const length = Math.floor(context.sampleRate * seconds)
  const buffer = context.createBuffer(1, length, context.sampleRate)
  const data = buffer.getChannelData(0)
  let seed = 90210
  for (let i = 0; i < length; i += 1) {
    seed = (seed * 1664525 + 1013904223) >>> 0
    data[i] = (seed / 4294967296) * 2 - 1
  }
  return buffer
}

function envelope(context, destination, time, duration, peak, attack = 0.008, release = 0.12) {
  const gain = context.createGain()
  const safePeak = Math.max(0.0001, peak)
  gain.gain.setValueAtTime(0.0001, time)
  gain.gain.exponentialRampToValueAtTime(safePeak, time + Math.max(0.002, attack))
  gain.gain.exponentialRampToValueAtTime(safePeak * 0.52, time + Math.max(attack + 0.01, duration * 0.55))
  gain.gain.exponentialRampToValueAtTime(0.0001, time + Math.max(attack + 0.03, duration + release))
  gain.connect(destination)
  return gain
}

function scheduleOscillator(context, destination, options) {
  const {
    time,
    duration,
    frequency,
    type = 'sine',
    gain = 0.05,
    attack = 0.01,
    release = 0.12,
    detune = 0,
    filterType = 'lowpass',
    filterFrequency = 5000,
    filterQ = 0.7,
    wet = 0,
  } = options
  if (time < 0 || frequency <= 0) return
  const oscillator = context.createOscillator()
  oscillator.type = type
  oscillator.frequency.setValueAtTime(frequency, time)
  oscillator.detune.setValueAtTime(detune, time)
  const filter = context.createBiquadFilter()
  filter.type = filterType
  filter.frequency.setValueAtTime(Math.min(18000, filterFrequency), time)
  filter.Q.setValueAtTime(filterQ, time)
  const amp = envelope(context, destination, time, duration, gain, attack, release)
  oscillator.connect(filter)
  filter.connect(amp)
  if (wet > 0 && destination.wetInput) {
    const send = context.createGain()
    send.gain.value = wet
    amp.connect(send)
    send.connect(destination.wetInput)
  }
  oscillator.start(time)
  oscillator.stop(time + duration + release + 0.08)
}

function scheduleKick(context, destination, time, velocity, noiseBuffer) {
  const oscillator = context.createOscillator()
  oscillator.type = 'sine'
  oscillator.frequency.setValueAtTime(148, time)
  oscillator.frequency.exponentialRampToValueAtTime(42, time + 0.12)
  const gain = context.createGain()
  gain.gain.setValueAtTime(0.0001, time)
  gain.gain.exponentialRampToValueAtTime(0.7 * velocity, time + 0.004)
  gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.36)
  const shaper = context.createWaveShaper()
  shaper.curve = makeSoftClip()
  oscillator.connect(gain)
  gain.connect(shaper)
  shaper.connect(destination)
  oscillator.start(time)
  oscillator.stop(time + 0.4)

  const click = context.createBufferSource()
  click.buffer = noiseBuffer
  click.playbackRate.value = 0.8
  const clickFilter = context.createBiquadFilter()
  clickFilter.type = 'lowpass'
  clickFilter.frequency.value = 1200
  const clickGain = context.createGain()
  clickGain.gain.setValueAtTime(0.14 * velocity, time)
  clickGain.gain.exponentialRampToValueAtTime(0.0001, time + 0.045)
  click.connect(clickFilter)
  clickFilter.connect(clickGain)
  clickGain.connect(destination)
  click.start(time)
  click.stop(time + 0.06)
}

function scheduleSnare(context, destination, time, velocity, noiseBuffer) {
  const source = context.createBufferSource()
  source.buffer = noiseBuffer
  source.playbackRate.value = 1.25
  const filter = context.createBiquadFilter()
  filter.type = 'bandpass'
  filter.frequency.value = 1900
  filter.Q.value = 0.8
  const gain = context.createGain()
  gain.gain.setValueAtTime(0.24 * velocity, time)
  gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.19)
  source.connect(filter)
  filter.connect(gain)
  gain.connect(destination)
  source.start(time)
  source.stop(time + 0.2)

  scheduleOscillator(context, destination, {
    time,
    duration: 0.08,
    frequency: 185,
    type: 'triangle',
    gain: 0.12 * velocity,
    attack: 0.002,
    release: 0.04,
  })
}

function scheduleHat(context, destination, time, velocity, noiseBuffer) {
  const source = context.createBufferSource()
  source.buffer = noiseBuffer
  source.playbackRate.value = 1.8
  const filter = context.createBiquadFilter()
  filter.type = 'highpass'
  filter.frequency.value = 7000
  const gain = context.createGain()
  gain.gain.setValueAtTime(0.055 * velocity, time)
  gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.045)
  source.connect(filter)
  filter.connect(gain)
  gain.connect(destination)
  source.start(time)
  source.stop(time + 0.055)
}

let softClipCurve = null
function makeSoftClip() {
  if (softClipCurve) return softClipCurve
  const samples = 1024
  softClipCurve = new Float32Array(samples)
  for (let i = 0; i < samples; i += 1) {
    const x = (i / (samples - 1)) * 2 - 1
    softClipCurve[i] = Math.tanh(x * 1.4)
  }
  return softClipCurve
}

function midiToFrequency(midi) {
  return 440 * 2 ** ((midi - 69) / 12)
}

/**
 * Render a built-in track offline. Returns a stereo AudioBuffer that can be
 * played through the normal imported-audio playback path.
 */
export async function renderTrackAudio(track) {
  if (!track.builtIn) throw new Error('renderTrackAudio only renders built-in tracks')
  const composition = buildComposition(track)
  const sampleRate = 44100
  const duration = Math.ceil(composition.duration * sampleRate)
  const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext
  const context = new OfflineContext(2, duration, sampleRate)
  const noise = makeNoiseBuffer(context, 2)

  const compressor = context.createDynamicsCompressor()
  compressor.threshold.value = -20
  compressor.knee.value = 18
  compressor.ratio.value = 4
  compressor.attack.value = 0.006
  compressor.release.value = 0.22

  const master = context.createGain()
  master.gain.value = 0.84
  master.connect(compressor)
  compressor.connect(context.destination)

  // A short stereo ping-pong echo gives the leads air without masking the beat.
  const delay = context.createDelay(1.5)
  delay.delayTime.value = composition.beat * 0.75
  const feedback = context.createGain()
  feedback.gain.value = 0.27
  const wetGain = context.createGain()
  wetGain.gain.value = 0.32
  delay.connect(feedback)
  feedback.connect(delay)
  delay.connect(wetGain)
  wetGain.connect(master)

  const dry = context.createGain()
  dry.gain.value = 1
  dry.wetInput = delay
  dry.connect(master)

  const warm = context.createBiquadFilter()
  warm.type = 'lowshelf'
  warm.frequency.value = 180
  warm.gain.value = 2.5
  warm.connect(dry)

  for (const pad of composition.pads) {
    if (pad.time >= composition.duration) continue
    pad.notes.forEach((midi, index) => {
      const pan = context.createStereoPanner()
      pan.pan.value = (index - 1) * 0.28
      pan.connect(warm)
      scheduleOscillator(context, pan, {
        time: pad.time,
        duration: pad.duration,
        frequency: midiToFrequency(midi),
        type: 'sawtooth',
        gain: 0.026 * pad.velocity,
        attack: 0.24,
        release: 0.45,
        detune: index === 1 ? 5 : -5,
        filterFrequency: 1500 + index * 240,
        filterQ: 0.9,
      })
      scheduleOscillator(context, pan, {
        time: pad.time,
        duration: pad.duration * 0.96,
        frequency: midiToFrequency(midi - 12),
        type: 'sine',
        gain: 0.02 * pad.velocity,
        attack: 0.3,
        release: 0.5,
      })
    })
  }

  for (const note of composition.bass) {
    if (note.time >= composition.duration) continue
    const filter = context.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.setValueAtTime(520, note.time)
    filter.frequency.exponentialRampToValueAtTime(190, note.time + note.duration)
    filter.Q.value = 2.2
    filter.connect(dry)
    scheduleOscillator(context, filter, {
      time: note.time,
      duration: note.duration,
      frequency: midiToFrequency(note.midi),
      type: 'sawtooth',
      gain: 0.15 * note.velocity,
      attack: 0.008,
      release: 0.12,
    })
    scheduleOscillator(context, dry, {
      time: note.time,
      duration: note.duration * 0.9,
      frequency: midiToFrequency(note.midi - 12),
      type: 'sine',
      gain: 0.12 * note.velocity,
      attack: 0.006,
      release: 0.1,
    })
  }

  for (const event of composition.events) {
    if (event.kind === 'bass') continue
    const pan = context.createStereoPanner()
    const lane = event.laneHint ?? 0
    pan.pan.value = (lane - 1.5) * 0.24
    pan.connect(dry)
    const frequency = midiToFrequency(event.midi)
    const long = event.duration > composition.beat * 0.8
    scheduleOscillator(context, pan, {
      time: event.time,
      duration: event.duration,
      frequency,
      type: 'triangle',
      gain: (long ? 0.05 : 0.06) * event.velocity,
      attack: 0.005,
      release: long ? 0.28 : 0.16,
      filterFrequency: long ? 3800 : 6200,
      filterQ: 1.1,
      wet: event.kind === 'harmony' ? 0.08 : 0.16,
    })
    scheduleOscillator(context, pan, {
      time: event.time,
      duration: Math.max(0.06, event.duration * 0.7),
      frequency: frequency * 2,
      type: 'sine',
      gain: 0.016 * event.velocity,
      attack: 0.003,
      release: 0.12,
      wet: 0.3,
    })
  }

  const sortedDrums = [...composition.drums].sort((a, b) => a.time - b.time)
  for (const drum of sortedDrums) {
    if (drum.time >= composition.duration) continue
    if (drum.type === 'kick') scheduleKick(context, dry, drum.time, drum.velocity, noise)
    else if (drum.type === 'snare') scheduleSnare(context, dry, drum.time, drum.velocity, noise)
    else scheduleHat(context, dry, drum.time, drum.velocity, noise)
  }

  // Gentle fade in/out prevents clicks when the source starts and ends.
  master.gain.setValueAtTime(0.0001, 0)
  master.gain.exponentialRampToValueAtTime(0.84, 0.08)
  master.gain.setValueAtTime(0.84, Math.max(0.1, composition.duration - 1.2))
  master.gain.exponentialRampToValueAtTime(0.0001, composition.duration - 0.02)

  return context.startRendering()
}

import { DIFFICULTIES, clamp, hashString, mulberry32 } from './data.js'
import { buildComposition } from './composition.js'

const chartCache = new Map()

function sourceEvents(track) {
  if (track.builtIn) {
    return buildComposition(track).events.map((event) => ({
      time: event.time,
      strength: event.strength,
      laneHint: event.laneHint,
      sustain: event.sustain,
    }))
  }
  return track.events || []
}

function groupClusters(events) {
  const clusters = []
  for (const event of events) {
    const last = clusters[clusters.length - 1]
    if (last && event.time - last.time <= 0.055) {
      last.events.push(event)
      last.time = (last.time * (last.events.length - 1) + event.time) / last.events.length
      last.strength = Math.max(last.strength, event.strength)
    } else {
      clusters.push({
        time: event.time,
        strength: event.strength,
        events: [event],
      })
    }
  }
  return clusters
}

function pickLane(cluster, freeAt, time, maxChord, random, difficulty) {
  const desired = []
  const ordered = [...cluster.events].sort((a, b) => b.strength - a.strength)

  for (const event of ordered) {
    if (desired.length >= maxChord) break
    const preferred = Number.isInteger(event.laneHint) ? event.laneHint : null
    if (preferred !== null && !desired.includes(preferred) && time >= freeAt[preferred]) {
      desired.push(preferred)
    }
  }

  let target = 1
  if (maxChord > 1) {
    const factor = 0.46 + cluster.strength * 0.75
    while (target < maxChord && random() < DIFFICULTIES[difficulty].chordChance * factor) {
      target += 1
    }
  }
  target = Math.max(target, Math.min(maxChord, cluster.events.length))

  if (desired.length < target) {
    const available = [0, 1, 2, 3].filter(
      (lane) => !desired.includes(lane) && time >= freeAt[lane],
    )
    while (desired.length < target && available.length) {
      const index = Math.floor(random() * available.length)
      desired.push(available.splice(index, 1)[0])
    }
  }

  return desired
}

function addFallbackClusters(clusters, track, difficulty, random) {
  const difficultyData = DIFFICULTIES[difficulty]
  const minCount = Math.floor(track.duration * (difficulty === 'normal' ? 0.55 : 0.85))
  if (clusters.length >= minCount) return clusters
  const beat = 60 / track.bpm
  const extra = []
  const step = difficulty === 'normal' ? beat : beat / 2
  for (let time = 1.1; time < track.duration - 1; time += step) {
    if (clusters.some((cluster) => Math.abs(cluster.time - time) < 0.11)) continue
    extra.push({
      time,
      strength: 0.42,
      events: [
        {
          time,
          strength: 0.42,
          laneHint: Math.floor(random() * 4),
          sustain: difficultyData.holdChance * 0.5,
        },
      ],
    })
  }
  return [...clusters, ...extra].sort((a, b) => a.time - b.time)
}

export function createChart(track, difficultyId) {
  const cacheKey = `${track.id}:${difficultyId}:${track.chartVersion || 0}`
  if (chartCache.has(cacheKey)) return chartCache.get(cacheKey)
  const difficulty = DIFFICULTIES[difficultyId]
  const random = mulberry32(hashString(`${track.id}:${difficultyId}:${track.seed || 0}`))
  const clusters = addFallbackClusters(
    groupClusters(sourceEvents(track)),
    track,
    difficultyId,
    random,
  )
  const notes = []
  const laneFreeAt = [0, 0, 0, 0]
  const firstAllowed = Math.max(0.85, Math.min(1.8, 60 / track.bpm))
  let lastTime = -999
  let selected = 0
  let noteCounter = 0

  for (const cluster of clusters) {
    const time = cluster.time
    if (time < firstAllowed || time > track.duration - 0.75) continue
    const gap = time - lastTime
    if (gap < difficulty.minGap) continue

    let accept = gap >= difficulty.gap
    if (!accept) {
      const pressure = gap / difficulty.gap
      const lucky = cluster.strength > 0.78 && random() < (pressure - 0.38) * 1.6
      if (!lucky) continue
      accept = true
    }
    if (!accept) continue

    const lanes = pickLane(
      cluster,
      laneFreeAt,
      time,
      difficulty.maxChord,
      random,
      difficultyId,
    )
    if (!lanes.length) continue

    let clusterAdded = 0
    for (const lane of lanes) {
      noteCounter += 1
      const candidates = cluster.events.filter((event) => event.laneHint === lane)
      const best = candidates.sort((a, b) => b.strength - a.strength)[0] || cluster.events[0]
      const forceHold =
        (noteCounter > 8 && noteCounter % (difficultyId === 'normal' ? 9 : 13) === 0) ||
        (selected === 2 && difficultyId !== 'demon')
      const wantsHold = best.sustain > 0.2 || difficultyId !== 'demon'
      const holdRoll = random()
      const shouldHold =
        forceHold ||
        (wantsHold &&
          holdRoll < difficulty.holdChance * (0.58 + cluster.strength * 0.7))
      let endTime = time
      if (shouldHold) {
        const natural = Math.max(0.62, Math.min(2.2, best.sustain || 0.8))
        const targetLength = Math.min(
          difficulty.holdMax,
          Math.max(0.56, natural * (difficultyId === 'normal' ? 1.08 : 0.9)),
        )
        endTime = Math.min(
          track.duration - 0.2,
          time + targetLength,
        )
        if (endTime - time >= 0.5) {
          laneFreeAt[lane] = endTime + 0.09
        } else {
          endTime = time
        }
      }
      if (endTime === time) {
        laneFreeAt[lane] = time + Math.max(0.09, difficulty.minGap * 0.7)
      }

      notes.push({
        id: `${track.id}-${difficultyId}-${notes.length}`,
        lane,
        time,
        type: endTime > time ? 'hold' : 'tap',
        endTime: endTime > time ? endTime : null,
        length: Math.max(0, endTime - time),
        strength: best.strength || cluster.strength,
        judged: false,
        active: false,
        broken: false,
        done: false,
        grade: null,
      })
      clusterAdded += 1
    }

    if (clusterAdded > 0) {
      selected += 1
      lastTime = time
    }
  }

  notes.sort((a, b) => a.time - b.time || a.lane - b.lane)
  const chart = {
    track,
    difficulty: difficultyId,
    notes,
    firstNote: notes[0]?.time ?? 0,
    lastNote: notes.reduce((max, note) => Math.max(max, note.endTime || note.time), 0),
    tapCount: notes.filter((note) => note.type === 'tap').length,
    holdCount: notes.filter((note) => note.type === 'hold').length,
  }
  chart.duration = track.duration
  chartCache.set(cacheKey, chart)
  return chart
}

export function getTravelTime(track, difficultyId) {
  const tempoFactor = clamp(120 / track.bpm, 0.67, 1.3)
  return DIFFICULTIES[difficultyId].fallTime * tempoFactor
}

export function getSpeedFactor(track, difficultyId) {
  return 2.3 / getTravelTime(track, difficultyId)
}

import { clamp } from './data.js'

let audioContext = null
let masterGain = null
let muted = false

export async function ensureAudioContext() {
  if (!audioContext) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext
    if (!AudioContextClass) throw new Error('Tu navegador no soporta Web Audio.')
    audioContext = new AudioContextClass({ latencyHint: 'interactive' })
    masterGain = audioContext.createGain()
    masterGain.gain.value = muted ? 0 : 0.9
    masterGain.connect(audioContext.destination)
  }
  if (audioContext.state === 'suspended') {
    await audioContext.resume()
  }
  return audioContext
}

export function getAudioContext() {
  return audioContext
}

export function getMasterGain() {
  return masterGain
}

export function setMuted(value) {
  muted = Boolean(value)
  if (masterGain && audioContext) {
    masterGain.gain.setTargetAtTime(muted ? 0 : 0.9, audioContext.currentTime, 0.02)
  }
  return muted
}

export function isMuted() {
  return muted
}

export function playHitPing(lane, quality = 'perfect') {
  if (!audioContext || !masterGain || muted || audioContext.state !== 'running') return
  const now = audioContext.currentTime
  const oscillator = audioContext.createOscillator()
  const gain = audioContext.createGain()
  const base = [392, 523.25, 659.25, 783.99][lane] || 440
  const qualityLift = quality === 'perfect' ? 2 : quality === 'great' ? 1.5 : 1
  oscillator.type = quality === 'perfect' ? 'sine' : 'triangle'
  oscillator.frequency.setValueAtTime(base * qualityLift, now)
  oscillator.frequency.exponentialRampToValueAtTime(base * qualityLift * 1.014, now + 0.08)
  gain.gain.setValueAtTime(0.0001, now)
  gain.gain.exponentialRampToValueAtTime(0.035, now + 0.006)
  gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.13)
  oscillator.connect(gain)
  gain.connect(masterGain)
  oscillator.start(now)
  oscillator.stop(now + 0.15)
}

export function playHoldPing(lane) {
  if (!audioContext || !masterGain || muted || audioContext.state !== 'running') return
  const now = audioContext.currentTime
  const oscillator = audioContext.createOscillator()
  const gain = audioContext.createGain()
  oscillator.type = 'sine'
  oscillator.frequency.value = ([196, 261.63, 329.63, 392][lane] || 220) * 2
  gain.gain.setValueAtTime(0.0001, now)
  gain.gain.exponentialRampToValueAtTime(0.025, now + 0.01)
  gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.22)
  oscillator.connect(gain)
  gain.connect(masterGain)
  oscillator.start(now)
  oscillator.stop(now + 0.24)
}

function yieldToBrowser() {
  return new Promise((resolve) => setTimeout(resolve, 0))
}

function downsample(buffer, targetRate) {
  const ratio = buffer.sampleRate / targetRate
  const length = Math.max(1, Math.floor(buffer.length / ratio))
  const mono = new Float32Array(length)
  const channels = []
  for (let channel = 0; channel < buffer.numberOfChannels; channel += 1) {
    channels.push(buffer.getChannelData(channel))
  }
  for (let i = 0; i < length; i += 1) {
    const start = Math.floor(i * ratio)
    const end = Math.min(buffer.length, Math.max(start + 1, Math.floor((i + 1) * ratio)))
    let sum = 0
    for (const data of channels) {
      for (let j = start; j < end; j += 1) sum += data[j]
    }
    mono[i] = sum / ((end - start) * channels.length)
  }
  return mono
}

function fft(re, im) {
  const n = re.length
  for (let i = 1, j = 0; i < n; i += 1) {
    let bit = n >> 1
    for (; j & bit; bit >>= 1) j ^= bit
    j ^= bit
    if (i < j) {
      const tr = re[i]
      re[i] = re[j]
      re[j] = tr
      const ti = im[i]
      im[i] = im[j]
      im[j] = ti
    }
  }
  for (let length = 2; length <= n; length <<= 1) {
    const angle = (-2 * Math.PI) / length
    const wLenRe = Math.cos(angle)
    const wLenIm = Math.sin(angle)
    const half = length >> 1
    for (let start = 0; start < n; start += length) {
      let wRe = 1
      let wIm = 0
      for (let j = 0; j < half; j += 1) {
        const uRe = re[start + j]
        const uIm = im[start + j]
        const vRe = re[start + j + half] * wRe - im[start + j + half] * wIm
        const vIm = re[start + j + half] * wIm + im[start + j + half] * wRe
        re[start + j] = uRe + vRe
        im[start + j] = uIm + vIm
        re[start + j + half] = uRe - vRe
        im[start + j + half] = uIm - vIm
        const nextWRe = wRe * wLenRe - wIm * wLenIm
        wIm = wRe * wLenIm + wIm * wLenRe
        wRe = nextWRe
      }
    }
  }
}

function detectOnsets(odf, bandEnergy, energy, frameRate) {
  const n = odf.length
  let globalMax = 0
  for (let i = 0; i < n; i += 1) globalMax = Math.max(globalMax, odf[i])
  if (globalMax <= 0) return []

  const normalized = new Float32Array(n)
  for (let i = 0; i < n; i += 1) normalized[i] = odf[i] / globalMax

  const onsets = []
  let lastPeak = -10
  for (let i = 2; i < n - 2; i += 1) {
    const value = normalized[i]
    if (value < 0.025) continue
    if (!(value >= normalized[i - 1] && value > normalized[i + 1])) continue

    const from = Math.max(0, i - 9)
    const to = Math.min(n - 1, i + 9)
    let localSum = 0
    let localCount = 0
    for (let j = from; j <= to; j += 1) {
      if (j === i) continue
      localSum += normalized[j]
      localCount += 1
    }
    const localMean = localSum / Math.max(1, localCount)
    const threshold = Math.max(0.045, localMean * 1.4 + 0.018)
    if (value < threshold) continue
    if (i - lastPeak < 2) continue

    const bands = [0, 1, 2, 3].map((band) => bandEnergy[i * 4 + band] || 0)
    let dominant = 0
    for (let band = 1; band < 4; band += 1) {
      if (bands[band] > bands[dominant]) dominant = band
    }

    const peakEnergy = energy[i] || 0
    let sustain = 0.12
    const maxLook = Math.min(n - 1, i + Math.round(frameRate * 2.2))
    for (let j = i + 3; j < maxLook; j += 2) {
      if ((energy[j] || 0) < peakEnergy * 0.38) break
      sustain = (j - i) / frameRate
    }
    if (sustain < 0.22) sustain = 0.12

    onsets.push({
      frame: i,
      time: i / frameRate - 0.015,
      strength: clamp((value - threshold) / Math.max(0.08, 1 - threshold), 0.12, 1),
      laneHint: dominant,
      sustain,
    })
    lastPeak = i
  }
  return onsets
}

function estimateTempo(odf, frameRate) {
  const n = odf.length
  const pulse = new Float32Array(n)
  let energy = 0
  for (let i = 0; i < n; i += 1) {
    const value = Math.max(0, odf[i] - 0.035)
    pulse[i] = value
    energy += value * value
  }
  if (!energy) return { bpm: 120, confidence: 0.1, lag: frameRate * 0.5 }

  const minBpm = 55
  const maxBpm = 200
  const minLag = Math.max(2, Math.floor((frameRate * 60) / maxBpm))
  const maxLag = Math.max(minLag + 1, Math.ceil((frameRate * 60) / minBpm))
  const scores = []
  for (let lag = minLag; lag <= maxLag; lag += 1) {
    let sum = 0
    let count = 0
    for (let i = lag; i < n; i += 1) {
      sum += pulse[i] * pulse[i - lag]
      count += 1
    }
    const correlation = count ? sum / count : 0
    const bpm = (60 * frameRate) / lag
    const prior = Math.exp(-0.5 * (Math.log(bpm / 116) / 0.37) ** 2)
    scores.push({ lag, bpm, correlation, score: correlation * prior })
  }
  scores.sort((a, b) => b.score - a.score)
  let best = scores[0]
  if (!best) return { bpm: 120, confidence: 0.1, lag: frameRate * 0.5 }

  const findNear = (bpm) => {
    const target = (60 * frameRate) / bpm
    let local = scores[0]
    for (const candidate of scores) {
      if (Math.abs(candidate.lag - target) <= 1.5) {
        if (candidate.correlation > local.correlation) local = candidate
      }
    }
    return local
  }

  if (best.bpm < 91) {
    const doubled = findNear(best.bpm * 2)
    if (doubled && doubled.bpm <= 195 && doubled.correlation > best.correlation * 0.7) {
      best = doubled
    }
  } else if (best.bpm > 166) {
    const halved = findNear(best.bpm / 2)
    if (halved && halved.bpm >= 76 && halved.correlation > best.correlation * 1.12) {
      best = halved
    }
  }

  const bpm = clamp(Math.round(best.bpm), 60, 200)
  const confidence = clamp(0.35 + (best.correlation / Math.max(0.0001, Math.sqrt(energy / n))) * 0.7, 0.25, 0.98)
  return { bpm, confidence, lag: best.lag, correlation: best.correlation }
}

function estimateBeatOffset(odf, lagFrames) {
  const n = odf.length
  const period = Math.max(2, Math.round(lagFrames))
  let bestOffset = 0
  let bestScore = -1
  for (let offset = 0; offset < period; offset += 1) {
    let score = 0
    for (let i = offset; i < n; i += period) {
      score += odf[i] || 0
      if (i + 1 < n) score += (odf[i + 1] || 0) * 0.4
    }
    if (score > bestScore) {
      bestScore = score
      bestOffset = offset
    }
  }
  return bestOffset
}

export async function analyzeBuffer(buffer, onProgress = () => {}) {
  const duration = buffer.duration
  const targetRate = 11025
  onProgress(0.1, 'Preparando forma de onda')
  await yieldToBrowser()
  const mono = downsample(buffer, targetRate)
  const frameRate = targetRate / 256
  const fftSize = 1024
  const hop = 256
  const frames = Math.max(1, Math.floor((mono.length - fftSize) / hop))
  const odf = new Float32Array(frames)
  const bandEnergy = new Float32Array(frames * 4)
  const energy = new Float32Array(frames)
  const window = new Float32Array(fftSize)
  for (let i = 0; i < fftSize; i += 1) {
    window[i] = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (fftSize - 1))
  }
  const re = new Float32Array(fftSize)
  const im = new Float32Array(fftSize)
  const previous = new Float32Array(fftSize / 2)
  const bandBins = [0, 0, 0, 0]
  for (let bin = 1; bin < fftSize / 2; bin += 1) {
    const frequency = (bin * targetRate) / fftSize
    if (frequency < 160) bandBins[0] += 1
    else if (frequency < 500) bandBins[1] += 1
    else if (frequency < 1500) bandBins[2] += 1
    else bandBins[3] += 1
  }

  onProgress(0.18, 'Leyendo energía del espectro')
  for (let frame = 0; frame < frames; frame += 1) {
    const start = frame * hop
    for (let i = 0; i < fftSize; i += 1) {
      re[i] = (mono[start + i] || 0) * window[i]
      im[i] = 0
    }
    fft(re, im)
    let flux = 0
    for (let bin = 1; bin < fftSize / 2; bin += 1) {
      const magnitude = Math.sqrt(re[bin] * re[bin] + im[bin] * im[bin])
      const compressed = Math.log1p(magnitude * 52)
      const difference = compressed - previous[bin]
      if (difference > 0) flux += difference * (1 + Math.log1p(bin) * 0.18)
      previous[bin] = compressed
      const frequency = (bin * targetRate) / fftSize
      const value = magnitude * magnitude
      if (frequency < 160) bandEnergy[frame * 4] += value
      else if (frequency < 500) bandEnergy[frame * 4 + 1] += value
      else if (frequency < 1500) bandEnergy[frame * 4 + 2] += value
      else if (frequency < 5000) bandEnergy[frame * 4 + 3] += value
    }
    odf[frame] = flux
    energy[frame] =
      bandEnergy[frame * 4] +
      bandEnergy[frame * 4 + 1] +
      bandEnergy[frame * 4 + 2] +
      bandEnergy[frame * 4 + 3]

    if (frame % 260 === 0) {
      onProgress(0.18 + (frame / frames) * 0.58, 'Detectando ataques y textura')
      await yieldToBrowser()
    }
  }

  onProgress(0.8, 'Midiendo el pulso de la pista')
  await yieldToBrowser()
  const tempo = estimateTempo(odf, frameRate)
  const offsetFrames = estimateBeatOffset(odf, tempo.lag)
  const beatOffset = offsetFrames / frameRate

  onProgress(0.9, 'Construyendo el mapa rítmico')
  await yieldToBrowser()
  const rawOnsets = detectOnsets(odf, bandEnergy, energy, frameRate)
  const events = []
  let previousTime = -1
  for (const onset of rawOnsets) {
    if (onset.time < 0.25 || onset.time > duration - 0.25) continue
    if (onset.time - previousTime < 0.048) continue
    events.push({
      time: onset.time,
      strength: clamp(onset.strength, 0.12, 1),
      laneHint: onset.laneHint,
      sustain: onset.sustain,
    })
    previousTime = onset.time
  }

  const peak = events.reduce((max, event) => Math.max(max, event.strength), 0.5)
  for (const event of events) event.strength = clamp(event.strength / peak, 0.1, 1)

  onProgress(1, 'Listo')
  return {
    bpm: tempo.bpm,
    beatOffset,
    duration,
    events,
    onsetCount: events.length,
    confidence: tempo.confidence,
  }
}

export async function decodeAudioFile(file, onProgress = () => {}) {
  const context = await ensureAudioContext()
  onProgress(0.03, 'Leyendo archivo')
  const arrayBuffer = await file.arrayBuffer()
  onProgress(0.07, 'Decodificando audio')
  const buffer = await context.decodeAudioData(arrayBuffer.slice(0))
  onProgress(0.12, `Pista de ${Math.round(buffer.duration)} s`)
  return buffer
}

export async function analyzeAudioFile(file, onProgress) {
  const buffer = await decodeAudioFile(file, onProgress)
  if (buffer.duration > 12 * 60) {
    throw new Error('La pista supera los 12 minutos. Elige un archivo más corto.')
  }
  const analysis = await analyzeBuffer(buffer, onProgress)
  return { buffer, analysis }
}

import { clamp, formatTime } from './data.js'
import { getAudioContext, getMasterGain, playHitPing, playHoldPing } from './audio-engine.js'
import { getTravelTime } from './chart.js'

const LANE_COLORS = [
  { main: '#43d9ff', light: '#b7f6ff', shadow: 'rgba(67, 217, 255, 0.52)', soft: 'rgba(67, 217, 255, 0.14)' },
  { main: '#a7ff66', light: '#e0ffc2', shadow: 'rgba(167, 255, 102, 0.48)', soft: 'rgba(167, 255, 102, 0.13)' },
  { main: '#b391ff', light: '#e9ddff', shadow: 'rgba(179, 145, 255, 0.5)', soft: 'rgba(179, 145, 255, 0.14)' },
  { main: '#ff7cbb', light: '#ffd6e9', shadow: 'rgba(255, 124, 187, 0.5)', soft: 'rgba(255, 124, 187, 0.13)' },
]

const GRADES = {
  perfect: { points: 1000, weight: 1, color: '#b9f8ff', label: 'PERFECT' },
  great: { points: 700, weight: 0.8, color: '#caff9b', label: 'GREAT' },
  good: { points: 400, weight: 0.55, color: '#ffdf8e', label: 'GOOD' },
}

function roundRect(context, x, y, width, height, radius) {
  const r = Math.min(radius, width / 2, height / 2)
  context.beginPath()
  context.moveTo(x + r, y)
  context.arcTo(x + width, y, x + width, y + height, r)
  context.arcTo(x + width, y + height, x, y + height, r)
  context.arcTo(x, y + height, x, y, r)
  context.arcTo(x, y, x + width, y, r)
  context.closePath()
}

function formatScore(score) {
  return Math.max(0, Math.round(score)).toLocaleString('es-ES')
}

export class RhythmGame {
  constructor(elements, callbacks = {}) {
    this.canvas = elements.canvas
    this.stage = elements.stage
    this.context = this.canvas.getContext('2d')
    this.countdown = elements.countdown
    this.countdownNumber = elements.countdownNumber
    this.scoreEl = elements.score
    this.comboEl = elements.combo
    this.accuracyEl = elements.accuracy
    this.timeEl = elements.time
    this.progressEl = elements.progress
    this.hudCombo = elements.hudCombo
    this.callbacks = callbacks
    this.running = false
    this.paused = false
    this.notes = []
    this.activeHolds = [null, null, null, null]
    this.pressedLanes = [false, false, false, false]
    this.laneFlash = [0, 0, 0, 0]
    this.bursts = []
    this.judgements = []
    this.beats = []
    this.metrics = null
    this.lastFrame = 0
    this.dpr = 1
    this.width = 0
    this.height = 0
    this.animationFrame = 0
    this.resizeObserver = new ResizeObserver(() => this.resize())
    this.resizeObserver.observe(this.stage)
    this.resize()
  }

  resize() {
    if (!this.stage) return
    const rect = this.stage.getBoundingClientRect()
    const width = Math.floor(rect.width)
    const height = Math.floor(rect.height)
    if (width <= 0 || height <= 0) return
    this.dpr = Math.min(window.devicePixelRatio || 1, 2)
    this.width = width
    this.height = height
    this.canvas.width = Math.floor(width * this.dpr)
    this.canvas.height = Math.floor(height * this.dpr)
    this.canvas.style.width = `${width}px`
    this.canvas.style.height = `${height}px`
    this.context.setTransform(this.dpr, 0, 0, this.dpr, 0, 0)
    this.padding = clamp(width * 0.032, 10, 30)
    this.laneWidth = (width - this.padding * 2) / 4
    this.judgeY = height - 48
    this.travelDistance = this.judgeY + 90
    this.calculateSpeed()
    if (this.running) this.draw()
  }

  calculateSpeed() {
    if (!this.track || !this.difficulty) return
    this.travelTime = getTravelTime(this.track, this.difficulty.id)
    this.speed = this.travelDistance / this.travelTime
  }

  async start({ track, chart, buffer }) {
    this.stopSource()
    const audio = getAudioContext()
    if (!audio) throw new Error('El audio no está listo.')
    this.track = track
    this.chart = chart
    this.buffer = buffer
    this.difficulty = this.chart.difficultyData
    this.notes = chart.notes.map((note) => ({
      ...note,
      judged: false,
      headJudged: false,
      active: false,
      broken: false,
      missed: false,
      done: false,
      grade: null,
      headGrade: null,
      headScore: 0,
    }))
    this.activeHolds = [null, null, null, null]
    this.pressedLanes = [false, false, false, false]
    this.laneFlash = [0, 0, 0, 0]
    this.bursts = []
    this.judgements = []
    this.beats = []
    this.metrics = {
      score: 0,
      combo: 0,
      maxCombo: 0,
      perfect: 0,
      great: 0,
      good: 0,
      miss: 0,
      holdComplete: 0,
      holdBreak: 0,
      judged: 0,
      weighted: 0,
      total: this.notes.length,
    }
    this.lastFrame = performance.now()
    this.running = true
    this.paused = false
    this.pausedSongTime = 0
    this.audio = audio
    this.master = getMasterGain()
    this.startDelay = 3.15
    this.anchorSongTime = 0
    this.anchorContextTime = audio.currentTime + this.startDelay
    this.source = this.createSource(0)
    this.source.start(this.anchorContextTime, 0)
    this.resize()
    this.updateHud(true)
    this.countdown.classList.remove('is-hidden')
    this.countdownNumber.textContent = '3'
    this.countdown.classList.remove('is-go')
    this.animationFrame = requestAnimationFrame((time) => this.loop(time))
  }

  createSource(offset) {
    const source = this.audio.createBufferSource()
    source.buffer = this.buffer
    source.connect(this.master)
    this.source = source
    return source
  }

  stopSource() {
    if (this.source) {
      try {
        this.source.stop()
      } catch {
        // Already stopped.
      }
      try {
        this.source.disconnect()
      } catch {
        // Already disconnected.
      }
      this.source = null
    }
  }

  getSongTime() {
    if (!this.running) return 0
    if (this.paused) return this.pausedSongTime
    return this.anchorSongTime + (this.audio.currentTime - this.anchorContextTime)
  }

  pause() {
    if (!this.running || this.paused) return
    this.pausedSongTime = this.getSongTime()
    this.paused = true
    this.stopSource()
    this.pressedLanes = [false, false, false, false]
    this.laneFlash = [0, 0, 0, 0]
    this.updateHud(true)
    this.draw()
    cancelAnimationFrame(this.animationFrame)
  }

  async resume() {
    if (!this.running || !this.paused) return
    const audio = await getAudioContext()
    this.audio = audio
    this.master = getMasterGain()
    this.paused = false
    const songTime = this.pausedSongTime
    const countdown = Math.max(0, -songTime)
    this.anchorSongTime = songTime
    this.anchorContextTime = audio.currentTime + Math.max(0.08, countdown)
    const offset = Math.max(0, Math.min(this.buffer.duration - 0.02, songTime))
    const source = this.createSource(offset)
    try {
      source.start(this.anchorContextTime, offset)
    } catch {
      // If the source can't resume, finish cleanly rather than freezing.
      this.finish()
      return
    }
    this.lastFrame = performance.now()
    this.animationFrame = requestAnimationFrame((time) => this.loop(time))
  }

  stop() {
    this.running = false
    this.paused = false
    this.stopSource()
    cancelAnimationFrame(this.animationFrame)
    this.notes = []
    this.bursts = []
    this.judgements = []
  }

  loop(time) {
    if (!this.running || this.paused) return
    const delta = clamp((time - this.lastFrame) / 1000, 0, 0.05)
    this.lastFrame = time
    const songTime = this.getSongTime()
    this.update(songTime, delta)
    this.draw()
    this.updateHud()
    this.animationFrame = requestAnimationFrame((next) => this.loop(next))
  }

  update(songTime, delta) {
    if (songTime >= this.track.duration + 0.18) {
      this.finish()
      return
    }

    this.updateCountdown(songTime)

    for (let lane = 0; lane < 4; lane += 1) {
      this.laneFlash[lane] = Math.max(0, this.laneFlash[lane] - delta * 4.4)
    }

    for (let i = this.bursts.length - 1; i >= 0; i -= 1) {
      const burst = this.bursts[i]
      burst.age += delta
      for (const particle of burst.particles) {
        particle.x += particle.vx * delta
        particle.y += particle.vy * delta
        particle.vy += 190 * delta
        particle.vx *= 0.985
      }
      if (burst.age > burst.life) this.bursts.splice(i, 1)
    }
    for (let i = this.judgements.length - 1; i >= 0; i -= 1) {
      this.judgements[i].age += delta
      if (this.judgements[i].age > this.judgements[i].life) this.judgements.splice(i, 1)
    }

    for (const note of this.notes) {
      if (note.done) continue
      if (!note.headJudged && !note.missed && songTime > note.time + this.difficulty.good) {
        this.missNote(note)
      }
      if (note.active && songTime >= note.endTime - 0.025) {
        this.completeHold(note)
      }
    }
  }

  updateCountdown(songTime) {
    if (songTime < -0.08) {
      const value = String(clamp(Math.ceil(-songTime), 1, 3))
      if (this.countdownNumber.textContent !== value) {
        this.countdownNumber.textContent = value
        this.countdownNumber.animate(
          [
            { transform: 'scale(0.7)', opacity: 0.2 },
            { transform: 'scale(1.04)', opacity: 1, offset: 0.35 },
            { transform: 'scale(1)', opacity: 1 },
          ],
          { duration: 420, easing: 'cubic-bezier(.2,.8,.2,1)' },
        )
      }
      this.countdown.classList.remove('is-hidden', 'is-go')
    } else if (songTime < 0.55) {
      if (this.countdownNumber.textContent !== 'GO') {
        this.countdownNumber.textContent = 'GO'
        this.countdown.classList.add('is-go')
        this.countdownNumber.animate(
          [
            { transform: 'scale(0.65)', opacity: 0 },
            { transform: 'scale(1.12)', opacity: 1, offset: 0.4 },
            { transform: 'scale(1)', opacity: 0.9 },
          ],
          { duration: 500, easing: 'cubic-bezier(.16,1,.3,1)' },
        )
      }
      this.countdown.classList.remove('is-hidden')
    } else {
      this.countdown.classList.add('is-hidden')
    }
  }

  pressLane(lane) {
    if (!this.running || this.paused) return
    if (this.pressedLanes[lane]) return
    this.pressedLanes[lane] = true
    this.laneFlash[lane] = 1
    const songTime = this.getSongTime()
    let best = null
    let bestDifference = Infinity

    for (const note of this.notes) {
      if (note.lane !== lane || note.headJudged || note.missed || note.done) continue
      const difference = Math.abs(note.time - songTime)
      if (difference <= this.difficulty.good && difference < bestDifference) {
        best = note
        bestDifference = difference
      }
    }

    if (!best) {
      if (this.activeHolds[lane]) return
      return
    }

    const grade =
      bestDifference <= this.difficulty.perfect
        ? 'perfect'
        : bestDifference <= this.difficulty.great
          ? 'great'
          : 'good'
    this.resolveHead(best, grade)
  }

  releaseLane(lane) {
    this.pressedLanes[lane] = false
    if (!this.running || this.paused) return
    const hold = this.activeHolds[lane]
    if (!hold || !hold.active) return
    const songTime = this.getSongTime()
    if (songTime < hold.endTime - 0.14) {
      this.breakHold(hold)
    } else {
      this.completeHold(hold)
    }
  }

  resolveHead(note, grade) {
    note.headJudged = true
    note.headGrade = grade
    note.grade = grade
    const gradeData = GRADES[grade]
    const multiplier = 1 + Math.min(60, this.metrics.combo) * 0.018
    const points = Math.round(gradeData.points * multiplier)
    note.headScore = points
    this.metrics.score += points
    this.metrics.combo += 1
    this.metrics.maxCombo = Math.max(this.metrics.maxCombo, this.metrics.combo)
    this.spawnHit(note.lane, grade, note.type === 'hold')
    playHitPing(note.lane, grade)

    if (note.type === 'hold') {
      note.active = true
      this.activeHolds[note.lane] = note
      playHoldPing(note.lane)
    } else {
      this.finalizeTap(note, grade)
    }
    this.pulseCombo()
  }

  finalizeTap(note, grade) {
    note.done = true
    const gradeData = GRADES[grade]
    this.metrics.judged += 1
    this.metrics.weighted += gradeData.weight
    this.metrics[grade] += 1
  }

  completeHold(note) {
    if (!note.active) return
    note.active = false
    note.done = true
    note.judged = true
    this.activeHolds[note.lane] = null
    const grade = note.headGrade || 'good'
    this.metrics.judged += 1
    this.metrics.weighted += GRADES[grade].weight
    this.metrics[grade] += 1
    this.metrics.holdComplete += 1
    const bonus = Math.round(420 * (1 + Math.min(40, this.metrics.combo) * 0.012))
    this.metrics.score += bonus
    this.spawnHoldComplete(note.lane)
    this.pulseCombo()
  }

  breakHold(note) {
    if (!note.active) return
    note.active = false
    note.done = true
    note.broken = true
    note.missed = true
    this.activeHolds[note.lane] = null
    this.metrics.judged += 1
    this.metrics.weighted += 0.08
    this.metrics.miss += 1
    this.metrics.holdBreak += 1
    this.metrics.combo = 0
    this.spawnMiss(note.lane)
    this.pulseCombo()
  }

  missNote(note) {
    note.missed = true
    note.headJudged = true
    note.done = true
    note.active = false
    if (this.activeHolds[note.lane] === note) this.activeHolds[note.lane] = null
    this.metrics.judged += 1
    this.metrics.miss += 1
    this.metrics.combo = 0
    this.spawnMiss(note.lane)
    this.pulseCombo()
  }

  pulseCombo() {
    if (!this.hudCombo) return
    this.hudCombo.classList.remove('is-pulsing')
    void this.hudCombo.offsetWidth
    this.hudCombo.classList.add('is-pulsing')
  }

  accuracy() {
    if (!this.metrics || !this.metrics.judged) return 100
    return (this.metrics.weighted / this.metrics.judged) * 100
  }

  spawnHit(lane, grade, isHold) {
    const color = isHold ? '#bff8ff' : LANE_COLORS[lane].main
    const x = this.laneCenter(lane)
    const y = this.judgeY
    const count = window.innerWidth < 680 ? 8 : 13
    const particles = []
    for (let i = 0; i < count; i += 1) {
      const angle = (Math.PI * 2 * i) / count + Math.random() * 0.4
      const speed = 80 + Math.random() * (grade === 'perfect' ? 240 : 150)
      particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 65,
        size: 1.5 + Math.random() * 3.2,
      })
    }
    this.bursts.push({
      x,
      y,
      age: 0,
      life: grade === 'perfect' ? 0.52 : 0.4,
      color,
      particles,
    })
    this.judgements.push({
      x,
      y: y - 84,
      text: GRADES[grade].label,
      color: GRADES[grade].color,
      age: 0,
      life: 0.62,
    })
  }

  spawnHoldComplete(lane) {
    const x = this.laneCenter(lane)
    this.bursts.push({
      x,
      y: this.judgeY,
      age: 0,
      life: 0.4,
      color: LANE_COLORS[lane].light,
      particles: Array.from({ length: 8 }, () => ({
        x,
        y: this.judgeY,
        vx: (Math.random() - 0.5) * 120,
        vy: -Math.random() * 180,
        size: 2 + Math.random() * 2,
      })),
    })
    this.judgements.push({
      x,
      y: this.judgeY - 116,
      text: 'HOLD',
      color: LANE_COLORS[lane].light,
      age: 0,
      life: 0.52,
    })
  }

  spawnMiss(lane) {
    this.judgements.push({
      x: this.laneCenter(lane),
      y: this.judgeY - 78,
      text: 'MISS',
      color: '#ff716c',
      age: 0,
      life: 0.52,
    })
  }

  laneCenter(lane) {
    return this.padding + this.laneWidth * (lane + 0.5)
  }

  laneMetrics(lane) {
    const width = this.laneWidth
    const center = this.laneCenter(lane)
    return {
      x: center - width * 0.5,
      center,
      width,
    }
  }

  updateHud(force = false) {
    if (!this.metrics) return
    const now = performance.now()
    if (!force && this.lastHudUpdate && now - this.lastHudUpdate < 55) return
    this.lastHudUpdate = now
    const songTime = clamp(this.getSongTime(), 0, this.track.duration)
    this.scoreEl.textContent = formatScore(this.metrics.score)
    this.comboEl.textContent = this.metrics.combo
    this.accuracyEl.textContent = `${this.accuracy().toFixed(1)}%`
    this.timeEl.textContent = `${formatTime(songTime)} / ${formatTime(this.track.duration)}`
    this.progressEl.style.width = `${clamp((songTime / this.track.duration) * 100, 0, 100)}%`
  }

  draw() {
    const context = this.context
    if (!this.width || !this.height || !this.context) return
    const width = this.width
    const height = this.height
    const songTime = this.getSongTime()
    context.clearRect(0, 0, width, height)
    this.drawLaneBackground(context, width, height)
    this.drawBeatGrid(context, songTime)
    this.drawLaneGlows(context, height)

    const visible = []
    for (const note of this.notes) {
      if (note.done && !note.broken) continue
      if (note.done && note.broken && note.missed) {
        // Broken holds fade away with the chart.
      }
      const headY = this.judgeY - (note.time - songTime) * this.speed
      const tailY = note.endTime
        ? this.judgeY - (note.endTime - songTime) * this.speed
        : headY
      if (headY < -160 || tailY > height + 180) continue
      visible.push({ note, headY, tailY })
    }

    for (const item of visible) {
      if (item.note.type === 'hold') this.drawHoldBody(context, item)
    }
    for (const item of visible) {
      this.drawNoteCap(context, item)
    }

    this.drawJudgeLine(context, width)
    this.drawEffects(context)
    this.drawStageEdge(context, width, height)
  }

  drawLaneBackground(context, width, height) {
    const laneWidth = this.laneWidth
    for (let lane = 0; lane < 4; lane += 1) {
      const x = this.padding + lane * laneWidth
      context.fillStyle = lane % 2 === 0 ? 'rgba(255,255,255,0.017)' : 'rgba(255,255,255,0.006)'
      context.fillRect(x, 0, laneWidth, height)
      if (lane > 0) {
        context.fillStyle = 'rgba(255,255,255,0.045)'
        context.fillRect(x - 0.5, 0, 1, height)
      }
      context.fillStyle = 'rgba(255,255,255,0.025)'
      context.fillRect(x + 0.5, 0, 1, height)
    }
    const edge = context.createLinearGradient(0, 0, width, 0)
    edge.addColorStop(0, 'rgba(4,7,14,0.76)')
    edge.addColorStop(0.14, 'rgba(4,7,14,0)')
    edge.addColorStop(0.86, 'rgba(4,7,14,0)')
    edge.addColorStop(1, 'rgba(4,7,14,0.76)')
    context.fillStyle = edge
    context.fillRect(0, 0, width, height)
  }

  drawBeatGrid(context, songTime) {
    if (!this.track) return
    const beat = 60 / this.track.bpm
    const spacing = beat * this.speed
    let step = 1
    while (spacing * step < 30) step *= 2
    const beatOffset = this.track.beatOffset || 0
    const first = Math.floor((songTime - 0.5) / beat)
    const last = Math.ceil((songTime + this.travelTime + 0.5) / beat)
    context.save()
    for (let index = first; index <= last; index += step) {
      const time = beatOffset + index * beat
      const y = this.judgeY - (time - songTime) * this.speed
      if (y < -2 || y > this.height + 2) continue
      const isBar = index % 4 === 0
      context.strokeStyle = isBar ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.026)'
      context.lineWidth = isBar ? 1.2 : 1
      context.beginPath()
      context.moveTo(this.padding + 2, y)
      context.lineTo(this.width - this.padding - 2, y)
      context.stroke()
    }
    context.restore()
  }

  drawLaneGlows(context, height) {
    for (let lane = 0; lane < 4; lane += 1) {
      const strength = Math.max(this.laneFlash[lane], this.pressedLanes[lane] ? 0.8 : 0)
      if (strength <= 0.01) continue
      const x = this.padding + lane * this.laneWidth
      const gradient = context.createLinearGradient(0, this.judgeY - 280, 0, height)
      gradient.addColorStop(0, 'rgba(0,0,0,0)')
      gradient.addColorStop(1, LANE_COLORS[lane].soft.replace(/0\.\d+\)/, `${0.22 * strength})`))
      context.fillStyle = gradient
      context.fillRect(x, this.judgeY - 280, this.laneWidth, height - this.judgeY + 280)
    }
  }

  noteWidth(lane) {
    const metrics = this.laneMetrics(lane)
    return Math.max(24, metrics.width * this.difficulty.noteWidth - 6)
  }

  noteHeight() {
    return Math.max(38, Math.min(this.difficulty.noteHeight, this.laneWidth * 1.14))
  }

  capRadius(lane) {
    return Math.min(this.noteWidth(lane) * 0.22, 17)
  }

  drawHoldBody(context, item) {
    const { note, headY, tailY } = item
    const width = this.noteWidth(note.lane)
    const color = LANE_COLORS[note.lane]
    const x = this.laneCenter(note.lane) - width * 0.36
    const bodyWidth = width * 0.72
    const top = Math.min(tailY, headY)
    const height = Math.max(4, headY - tailY)
    const active = note.active
    const broken = note.broken
    context.save()
    if (note.done && note.missed) context.globalAlpha = 0.18
    else if (broken) context.globalAlpha = 0.35
    const gradient = context.createLinearGradient(0, tailY, 0, headY)
    if (active) {
      gradient.addColorStop(0, 'rgba(255,255,255,0.24)')
      gradient.addColorStop(0.5, LANE_COLORS[note.lane].soft)
      gradient.addColorStop(1, color.main)
    } else {
      gradient.addColorStop(0, 'rgba(255,255,255,0.08)')
      gradient.addColorStop(1, color.main)
    }
    context.shadowColor = active ? color.shadow : 'rgba(0,0,0,0)'
    context.shadowBlur = active ? 26 : 0
    context.globalAlpha *= active ? 0.78 : 0.45
    roundRect(context, x, top, bodyWidth, height, bodyWidth / 2)
    context.fillStyle = gradient
    context.fill()

    context.shadowBlur = 0
    context.strokeStyle = active ? color.light : color.main
    context.globalAlpha *= 0.72
    context.lineWidth = 1
    roundRect(context, x + 0.5, top, bodyWidth - 1, height, bodyWidth / 2)
    context.stroke()

    if (height > 26) {
      context.save()
      roundRect(context, x, top, bodyWidth, height, bodyWidth / 2)
      context.clip()
      context.strokeStyle = 'rgba(255,255,255,0.2)'
      context.lineWidth = 1
      const spacing = 18
      const shift = (this.getSongTime() * this.speed * 0.55) % spacing
      for (let y = top + shift; y < headY; y += spacing) {
        context.beginPath()
        context.moveTo(x + bodyWidth * 0.2, y)
        context.lineTo(x + bodyWidth * 0.8, y)
        context.stroke()
      }
      context.restore()
    }
    context.restore()
  }

  drawNoteCap(context, item) {
    const { note, headY } = item
    const width = this.noteWidth(note.lane)
    const height = this.noteHeight()
    const x = this.laneCenter(note.lane) - width / 2
    const y = headY - height / 2
    const color = LANE_COLORS[note.lane]
    const broken = note.broken
    const isHold = note.type === 'hold'
    context.save()
    if (note.done && note.missed) {
      context.globalAlpha = 0.2
    } else if (broken) {
      context.globalAlpha = 0.32
    }
    context.shadowColor = broken ? 'rgba(255,80,80,0.18)' : color.shadow
    context.shadowBlur = this.pressedLanes[note.lane] ? 28 : 17
    const gradient = context.createLinearGradient(0, y, 0, y + height)
    if (broken) {
      gradient.addColorStop(0, '#6d5157')
      gradient.addColorStop(1, '#382a31')
    } else {
      gradient.addColorStop(0, color.light)
      gradient.addColorStop(0.42, color.main)
      gradient.addColorStop(1, color.main)
    }
    roundRect(context, x, y, width, height, this.capRadius(note.lane))
    context.fillStyle = gradient
    context.fill()
    context.shadowBlur = 0
    context.strokeStyle = 'rgba(255,255,255,0.34)'
    context.lineWidth = 1.2
    roundRect(context, x + 0.6, y + 0.6, width - 1.2, height - 1.2, this.capRadius(note.lane))
    context.stroke()

    context.globalAlpha *= isHold ? 0.7 : 0.5
    context.fillStyle = 'rgba(255,255,255,0.4)'
    roundRect(context, x + width * 0.16, y + 7, width * 0.68, 2, 1)
    context.fill()
    context.globalAlpha = 1

    if (isHold) {
      context.strokeStyle = 'rgba(10,15,22,0.28)'
      context.lineWidth = 2
      context.beginPath()
      context.moveTo(x + width * 0.3, y + height * 0.72)
      context.lineTo(x + width * 0.5, y + height * 0.5)
      context.lineTo(x + width * 0.7, y + height * 0.72)
      context.stroke()
    }
    if (note.active) {
      context.globalAlpha = 0.55
      context.strokeStyle = '#ffffff'
      context.lineWidth = 1.4
      roundRect(context, x - 3, y - 3, width + 6, height + 6, this.capRadius(note.lane) + 2)
      context.stroke()
    }
    context.restore()
  }

  drawJudgeLine(context, width) {
    const gradient = context.createLinearGradient(0, 0, width, 0)
    gradient.addColorStop(0, 'rgba(255,255,255,0)')
    gradient.addColorStop(0.08, 'rgba(255,255,255,0.5)')
    gradient.addColorStop(0.5, 'rgba(255,255,255,0.96)')
    gradient.addColorStop(0.92, 'rgba(255,255,255,0.5)')
    gradient.addColorStop(1, 'rgba(255,255,255,0)')
    context.save()
    context.shadowColor = 'rgba(170,235,255,0.7)'
    context.shadowBlur = 16
    context.fillStyle = gradient
    context.fillRect(this.padding, this.judgeY - 1, width - this.padding * 2, 2)
    context.shadowBlur = 0
    for (let lane = 0; lane < 4; lane += 1) {
      const x = this.laneCenter(lane)
      context.fillStyle = this.pressedLanes[lane]
        ? LANE_COLORS[lane].light
        : 'rgba(255,255,255,0.65)'
      context.beginPath()
      context.arc(x, this.judgeY, this.pressedLanes[lane] ? 4 : 2.2, 0, Math.PI * 2)
      context.fill()
    }
    context.restore()
  }

  drawStageEdge(context, width, height) {
    const topFade = context.createLinearGradient(0, 0, 0, 74)
    topFade.addColorStop(0, 'rgba(5,8,15,0.9)')
    topFade.addColorStop(1, 'rgba(5,8,15,0)')
    context.fillStyle = topFade
    context.fillRect(0, 0, width, 74)
    const bottomFade = context.createLinearGradient(0, height - 30, 0, height)
    bottomFade.addColorStop(0, 'rgba(5,8,15,0)')
    bottomFade.addColorStop(1, 'rgba(5,8,15,0.8)')
    context.fillStyle = bottomFade
    context.fillRect(0, height - 30, width, 30)
  }

  drawEffects(context) {
    context.save()
    context.globalCompositeOperation = 'lighter'
    for (const burst of this.bursts) {
      const progress = burst.age / burst.life
      const alpha = 1 - progress
      context.globalAlpha = alpha * 0.9
      context.strokeStyle = burst.color
      context.lineWidth = 2
      context.beginPath()
      context.arc(burst.x, burst.y, 8 + progress * 42, 0, Math.PI * 2)
      context.stroke()
      for (const particle of burst.particles) {
        context.fillStyle = burst.color
        context.globalAlpha = alpha
        context.beginPath()
        context.arc(particle.x, particle.y, particle.size * (1 - progress * 0.7), 0, Math.PI * 2)
        context.fill()
      }
    }
    context.restore()

    for (const judgement of this.judgements) {
      const progress = judgement.age / judgement.life
      context.save()
      context.globalAlpha = Math.sin((1 - progress) * Math.PI * 0.86)
      context.fillStyle = judgement.color
      context.font = `700 ${clamp(this.width * 0.018, 10, 14)}px "Space Mono", monospace`
      context.textAlign = 'center'
      context.letterSpacing = '0.08em'
      context.shadowColor = judgement.color
      context.shadowBlur = 12
      context.fillText(judgement.text, judgement.x, judgement.y - progress * 24)
      context.restore()
    }
  }

  finish() {
    if (!this.running) return
    this.running = false
    this.paused = false
    this.stopSource()
    cancelAnimationFrame(this.animationFrame)
    this.countdown.classList.add('is-hidden')
    const accuracy = this.accuracy()
    const {
      perfect,
      great,
      good,
      miss,
      maxCombo,
      holdComplete,
      holdBreak,
      total,
    } = this.metrics
    let grade = 'D'
    let gradeLabel = 'Sigue intentando'
    if (miss === 0 && accuracy >= 99) {
      grade = 'S+'
      gradeLabel = 'Ritmo perfecto'
    } else if (accuracy >= 96 && miss <= 2) {
      grade = 'S'
      gradeLabel = 'Impecable'
    } else if (accuracy >= 90) {
      grade = 'A'
      gradeLabel = 'Gran control'
    } else if (accuracy >= 80) {
      grade = 'B'
      gradeLabel = 'Buen pulso'
    } else if (accuracy >= 66) {
      grade = 'C'
      gradeLabel = 'En progreso'
    }
    const result = {
      track: this.track,
      difficulty: this.difficulty,
      score: Math.round(this.metrics.score),
      accuracy,
      maxCombo,
      perfect,
      great,
      good,
      miss,
      holdComplete,
      holdBreak,
      total,
      grade,
      gradeLabel,
    }
    this.draw()
    if (this.callbacks.onFinish) this.callbacks.onFinish(result)
  }
}

import {
