input.command:
cat > /tmp/render-eval.js <<'EOF'
async () => {
  const { BUILT_IN_TRACKS } = await import('/js/data.js');
  const { renderTrackAudio } = await import('/js/composition.js');
  const track = BUILT_IN_TRACKS[0];
  const started = performance.now();
  const buffer = await renderTrackAudio(track);
  const renderMs = performance.now() - started;
  const numCh = buffer.numberOfChannels, len = buffer.length, sr = buffer.sampleRate;
  const dataSize = len * numCh * 2;
  const ab = new ArrayBuffer(44 + dataSize);
  const view = new DataView(ab);
  const writeStr = (offset, str) => { for (let i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i)); };
  writeStr(0, 'RIFF'); view.setUint32(4, 36 + dataSize, true); writeStr(8, 'WAVE');
  writeStr(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
  view.setUint16(22, numCh, true); view.setUint32(24, sr, true); view.setUint32(28, sr * numCh * 2, true);
  view.setUint16(32, numCh * 2, true); view.setUint16(34, 16, true);
  writeStr(36, 'data'); view.setUint32(40, dataSize, true);
  const channels = Array.from({ length: numCh }, (_, i) => buffer.getChannelData(i));
  let offset = 44;
  for (let i = 0; i < len; i++) {
    for (let ch = 0; ch < numCh; ch++) {
      const sample = Math.max(-1, Math.min(1, channels[ch][i]));
      view.setInt16(offset, sample < 0 ? sample * 0x8000 : sample * 0x7fff, true);
      offset += 2;
    }
  }
  const res = await fetch('http://localhost:3003/save?id=' + track.id, { method: 'POST', body: ab });
  return { id: track.id, duration: buffer.duration, renderMs, saved: await res.json() };
}
EOF
