import { writeFileSync } from 'node:fs'
const sr=44100,dur=12,ch=2,bpm=124,beat=60/bpm
const len=Math.floor(sr*dur)
const data=new Float32Array(len)
const kickAt=new Set()
for(let t=0;t<dur;t+=beat){kickAt.add(Math.round(t*sr))}
for(let i=0;i<len;i++){
  const t=i/sr
  const phase=(t%beat)/beat
  let s=0
  // kick
  const k=Math.exp(-phase*12)*Math.sin(2*Math.PI*(52+70*Math.exp(-phase*20))*t)
  s+=k*0.65
  // snare on beat 2/4
  const beatIndex=Math.floor(t/beat)
  if(beatIndex%4===1||beatIndex%4===3){const p=(t%beat); s+=(Math.random()*2-1)*Math.exp(-p*25)*0.18}
  // hats every half beat
  const hp=(t%(beat/2))/(beat/2)
  s+=(Math.random()*2-1)*Math.exp(-hp*60)*0.07
  // bass/lead
  const note=[0,3,5,7,5,3,7,10][Math.floor(t/beat)%8]
  const freq=110*Math.pow(2,note/12)
  s+=Math.sin(2*Math.PI*freq*t)*0.12
  s+=Math.sin(2*Math.PI*freq*2*t)*0.04
  data[i]=Math.max(-1,Math.min(1,s))
}
const bytes=len*ch*2, ab=new ArrayBuffer(44+bytes), v=new DataView(ab)
const ws=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))}
ws(0,'RIFF');v.setUint32(4,36+bytes,true);ws(8,'WAVE');ws(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,ch,true);v.setUint32(24,sr,true);v.setUint32(28,sr*ch*2,true);v.setUint16(32,ch*2,true);v.setUint16(34,16,true);ws(36,'data');v.setUint32(40,bytes,true)
let o=44
for(let i=0;i<len;i++){const s=Math.round(Math.max(-1,Math.min(1,data[i]))*32767);v.setInt16(o,s,true);v.setInt16(o+2,s,true);o+=4}
writeFileSync('/tmp/test-beat.wav',Buffer.from(ab))
console.log('wrote',bytes)
EOF
